res.format = function(obj) {
  if (typeof obj !== 'object' || obj === null) {
    throw new TypeError('Expected an object');
  }

  const defaultType = 'default';
  const types = Object.keys(obj);
  const accept = this.get('Accept');

  if (accept) {
    const best = negotiate(accept, types);
    if (best) {
      this.type(best);
      this.send(obj[best]);
      return;
    }
  }

  if (obj[defaultType]) {
    this.type(defaultType);
    this.send(obj[defaultType]);
  } else {
    this.status(406).send('Not Acceptable');
  }
};

function negotiate(accept, types) {
  const parsed = parseAcceptHeader(accept);
  for (const type of parsed) {
    if (types.includes(type.type)) {
      return type.type;
    }
  }
  return null;
}

function parseAcceptHeader(accept) {
  return accept
    .split(',')
    .map((item) => {
      const [type, ...params] = item.trim().split(';').map((part) => part.trim());
      const quality = params.find((param) => param.startsWith('q='))?.split('=')[1] || '1';
      return { type, quality: parseFloat(quality) };
    })
    .sort((a, b) => b.quality - a.quality);
}

