res.format = function(obj) {
  if (!obj || typeof obj !== 'object') {
    throw new Error('Invalid argument: expected an object');
  }

  const defaultType = '*/*';
  let acceptedTypes = this.get('Accept') || defaultType;
  acceptedTypes = acceptedTypes.split(',').map(type => type.trim());

  let chosenType = defaultType;
  for (const type in obj) {
    if (acceptedTypes.includes(type)) {
      chosenType = type;
      break;
    }
  }

  if (typeof obj[chosenType] !== 'function') {
    throw new Error(`No handler for content type: ${chosenType}`);
  }

  const body = obj[chosenType]();
  this.set('Content-Type', chosenType);
  this.send(body);
};

