  var types = this.accepts(Object.keys(obj));
  var type = types[0];

  if (!type) {
    this.status(406).send('Not Acceptable');
    return this;
  }

  // Normalize the type
  var normalizedType = this.app.utils.normalizeType(type);

  // Send the response in the determined type
  this.set('Content-Type', normalizedType.value);
  this.send(obj[type]);

  return this;
}

