function format(obj) {
  // Check if the object is empty
  if (!obj || Object.keys(obj).length === 0) {
    return this;
  }

  // Determine the best content type based on the request's accept header
  var types = Object.keys(obj);
  var best = this.accepts(types);

  // If no best type is found, return 406 Not Acceptable
  if (!best) {
    this.status(406).end();
    return this;
  }

  // Call the function associated with the best content type
  var fn = obj[best];
  if (typeof fn !== 'function') {
    throw new TypeError('Content type handler must be a function');
  }

  fn.call(this);
  return this;
}
